#!/bin/sh
# Regenerates what is compiled into the binary and the MCP bundle's sources from the repository files:
#   BuiltinRulesData.swift   from rules/muse.json
#   BuiltinKeysetData.swift  from keys/keyset.json + keys/keyset.json.sig (empty strings while the keyset is unsigned)
#   mcp/src/keyset-data.js   the same keyset, for the MCP server (which verifies binary manifests with it)
# Run after editing rules/muse.json or after signing the keyset, then rebuild the bundle (`npm run build` in
# bridge/muse/mcp). Swift and Node tests fail when the generated files drift from the repository files.
set -eu
here=$(cd "$(dirname "$0")" && pwd)
src="${1:-$here/../../rules/muse.json}"
keys="${CBB_KEYS_DIR:-$here/../../keys}"
swift_out="${CBB_SWIFT_OUT_DIR:-$here/../bridge/muse/Sources/MuseAXCore}"
js_out="${CBB_JS_OUT:-$here/../bridge/muse/mcp/src/keyset-data.js}"
[ -f "$src" ] || { echo "sync-builtin-rules.sh: $src not found" >&2; exit 1; }
if grep -q '"""#' "$src"; then echo "sync-builtin-rules.sh: rules contain a Swift raw-string terminator" >&2; exit 1; fi

out="$swift_out/BuiltinRulesData.swift"
{
  echo '// GENERATED by plugin/scripts/sync-builtin-rules.sh from rules/muse.json. Do not edit by hand.'
  echo 'enum BuiltinRulesData {'
  echo '    static let json = #"""'
  cat "$src"
  echo '"""#'
  echo '}'
} > "$out.tmp"
mv -f "$out.tmp" "$out"
echo "wrote $out"

kjson=""; ksig=""
if [ -f "$keys/keyset.json" ] && [ -f "$keys/keyset.json.sig" ]; then
  kjson=$(base64 < "$keys/keyset.json" | tr -d '\n')
  ksig=$(tr -d '[:space:]' < "$keys/keyset.json.sig")
else
  echo "keyset is unsigned (no keys/keyset.json.sig): compiling in an empty keyset"
fi
out="$swift_out/BuiltinKeysetData.swift"
{
  echo '// GENERATED by plugin/scripts/sync-builtin-rules.sh from keys/keyset.json and keys/keyset.json.sig. Do not edit by hand.'
  echo '// Both strings are empty until the maintainer has signed a keyset (keys/UNSIGNED present).'
  echo 'enum BuiltinKeysetData {'
  echo "    static let jsonBase64 = \"$kjson\""
  echo "    static let signature = \"$ksig\""
  echo '}'
} > "$out.tmp"
mv -f "$out.tmp" "$out"
echo "wrote $out"

{
  echo '// GENERATED by plugin/scripts/sync-builtin-rules.sh from keys/keyset.json and keys/keyset.json.sig. Do not edit by hand.'
  echo '// Both strings are empty until the maintainer has signed a keyset (keys/UNSIGNED present).'
  echo "export const BUNDLED_KEYSET = { jsonBase64: \"$kjson\", signature: \"$ksig\" };"
} > "$js_out.tmp"
mv -f "$js_out.tmp" "$js_out"
echo "wrote $js_out"
